function Get-WeekdayName {
    param([datetime]$Date, $T)
    $key = @('wdSun','wdMon','wdTue','wdWed','wdThu','wdFri','wdSat')[[int]$Date.DayOfWeek]
    if ($T -and $T.ContainsKey($key)) { return $T[$key] }
    return $Date.ToString('ddd')
}

function Format-Mail {
    # Replaces {key} placeholders with values. PowerShell 5.1's -f operator does
    # not accept a hashtable, so the reminder scripts call this instead.
    param([string]$Template, [hashtable]$Vars)
    if (-not $Template) { return '' }
    $out = $Template
    foreach ($k in $Vars.Keys) { $out = $out.Replace('{' + $k + '}', [string]$Vars[$k]) }
    return $out
}